Q: JSF commandbutton not being called when adding primefaces ajax A: <pre><code>import java.io.*;
import java.text.Normalizer;
import java.util.*;
import java.util.regex.Pattern;

public class TestIndemnisationEligibilite {

  public static synchronized boolean compareEligibility(Map&lt;String, Object&gt; param) throws IOException {

    boolean error = false;

    String fileName = (String) param.get(&quot;outputFile&quot;);
    FileWriter output = new FileWriter(fileName, true);
    BufferedWriter bw = new BufferedWriter(output);

    Map&lt;String, Object&gt; response = castMap(param.get(&quot;response&quot;));
    Map&lt;String, Object&gt; expected = castMap(param.get(&quot;expected&quot;));

    Map&lt;String, Object&gt; actER = castMap(response.get(&quot;eligibilityResponse&quot;));
    Map&lt;String, Object&gt; expER = castMap(expected.get(&quot;eligibilityResponse&quot;));

    String actStatus = str(actER.get(&quot;globalStatus&quot;));
    String expStatus = str(expER.get(&quot;globalStatus&quot;));

    // 1) globalStatus must match
    if (!Objects.equals(actStatus, expStatus)) {
      error = true;
      bw.write(&quot;ERROR: globalStatus mismatch. expected=&quot; + expStatus + &quot; actual=&quot; + actStatus);
      bw.newLine();
      bw.close();
      return error;
    }

    // 2) expected reason / clientReason
    String expReason = str(expER.get(&quot;reason&quot;));
    String expClientReason = str(expER.get(&quot;clientReason&quot;));

    String expReasonN = normalize(expReason);
    String expClientReasonN = normalize(expClientReason);

    // 3) actual nonEligibleRules[] (can be 1 or many)
    List&lt;Map&lt;String, Object&gt;&gt; actRules = castListOfMaps(actER.get(&quot;nonEligibleRules&quot;));

    if (actRules.isEmpty()) {
      // if expected has reason/clientReason but actual has no rules =&gt; mismatch
      if (!expReasonN.isEmpty() || !expClientReasonN.isEmpty()) {
        error = true;
        bw.write(&quot;ERROR: expected has reason/clientReason but actual nonEligibleRules is empty.&quot;);
        bw.newLine();
      }
      bw.close();
      return error;
    }

    boolean found = false;

    for (int i = 0; i &lt; actRules.size(); i++) {
      Map&lt;String, Object&gt; rule = actRules.get(i);

      String actReason = str(rule.get(&quot;reason&quot;));
      String actClientReason = str(rule.get(&quot;clientReason&quot;));

      String actReasonN = normalize(actReason);
      String actClientReasonN = normalize(actClientReason);

      if (expReasonN.equals(actReasonN) &amp;&amp; expClientReasonN.equals(actClientReasonN)) {
        found = true;
        break;
      }
    }

    if (!found) {
      error = true;
      bw.write(&quot;ERROR: No matching rule found in actual nonEligibleRules.&quot;);
      bw.newLine();
      bw.write(&quot;Expected reason(norm): &quot; + expReasonN);
      bw.newLine();
      bw.write(&quot;Expected clientReason(norm): &quot; + expClientReasonN);
      bw.newLine();
      bw.write(&quot;Actual candidates:&quot;);
      bw.newLine();

      for (int i = 0; i &lt; actRules.size(); i++) {
        Map&lt;String, Object&gt; rule = actRules.get(i);
        bw.write(&quot; - [&quot; + i + &quot;] reason(norm)=&quot; + normalize(str(rule.get(&quot;reason&quot;))));
        bw.newLine();
        bw.write(&quot;       clientReason(norm)=&quot; + normalize(str(rule.get(&quot;clientReason&quot;))));
        bw.newLine();
      }
    }

    bw.close();
    return error;
  }

  // ---------------- helpers ----------------

  private static String str(Object o) {
    return o == null ? &quot;&quot; : String.valueOf(o);
  }

  @SuppressWarnings(&quot;unchecked&quot;)
  private static Map&lt;String, Object&gt; castMap(Object o) {
    if (o == null) return new LinkedHashMap&lt;&gt;();
    if (o instanceof Map) return (Map&lt;String, Object&gt;) o;
    return new LinkedHashMap&lt;&gt;();
  }

  @SuppressWarnings(&quot;unchecked&quot;)
  private static List&lt;Map&lt;String, Object&gt;&gt; castListOfMaps(Object o) {
    if (o == null) return new ArrayList&lt;&gt;();
    if (o instanceof List) {
      List&lt;?&gt; list = (List&lt;?&gt;) o;
      List&lt;Map&lt;String, Object&gt;&gt; out = new ArrayList&lt;&gt;();
      for (Object item : list) {
        if (item instanceof Map) out.add((Map&lt;String, Object&gt;) item);
      }
      return out;
    }
    // sometimes if only 1 rule, it may come as a Map instead of list
    if (o instanceof Map) {
      List&lt;Map&lt;String, Object&gt;&gt; out = new ArrayList&lt;&gt;();
      out.add((Map&lt;String, Object&gt;) o);
      return out;
    }
    return new ArrayList&lt;&gt;();
  }

  private static final Pattern ACCENTS = Pattern.compile(&quot;\\p{M}+&quot;);
  private static final Pattern BRACKETS = Pattern.compile(&quot;\\[[^\\]]*\\]&quot;);
  private static final Pattern CONTRACT_NUM = Pattern.compile(&quot;\\b\\d{2,}/\\d{1,}\\b&quot;);

  private static String normalize(String s) {
    if (s == null) return &quot;&quot;;
    s = s.trim();

    // remove [nom commercial] [convention]
    s = BRACKETS.matcher(s).replaceAll(&quot; &quot;);

    // remove contract numbers like 2090/463
    s = CONTRACT_NUM.matcher(s).replaceAll(&quot; &quot;);

    // cut the dynamic tail (this is the &quot;last thing&quot; you said must be ignored)
    // You can add more cut keywords if needed.
    s = cutAfter(s, &quot;prevu par le contrat&quot;);
    s = cutAfter(s, &quot;prévu par le contrat&quot;);
    s = cutAfter(s, &quot;par le contrat&quot;);
    s = cutAfter(s, &quot;pour le contrat&quot;);
    s = cutAfter(s, &quot;au titre du contrat&quot;);
    s = cutAfter(s, &quot;contrat &quot;);

    // lowercase + remove accents
    String n = Normalizer.normalize(s, Normalizer.Form.NFD);
    n = ACCENTS.matcher(n).replaceAll(&quot;&quot;);

    // unify apostrophes
    n = n.replace('’', '\'').replace('‘', '\'');
    n = n.replaceAll(&quot;\\s+&quot;, &quot; &quot;).trim().toLowerCase();

    return n;
  }

  private static String cutAfter(String s, String keyword) {
    if (s == null) return &quot;&quot;;
    String low = s.toLowerCase();
    String key = keyword.toLowerCase();

    int idx = low.indexOf(key);
    if (idx &gt;= 0) {
      return s.substring(0, idx).trim();
    }
    return s;
  }
}
</code></pre>

Q: How do I set the AWS peering connection DNS resolution options through CloudFormation? A: <p>There has been an <a href="https://github.com/aws-cloudformation/cloudformation-coverage-roadmap/issues/154" rel="nofollow noreferrer">open feature request</a> for years now. There's always the option of adding a custom resource as a workaround for missing out-of-the-box CloudFormation features (from linked feature request):</p>
<pre class="lang-json prettyprint-override"><code>{
    &quot;Resources&quot;: {
        &quot;VpcPeeringOptionsRole&quot;: {
            &quot;Type&quot;: &quot;AWS::IAM::Role&quot;,
            &quot;Properties&quot;: {
                &quot;Path&quot;: &quot;/&quot;,
                &quot;AssumeRolePolicyDocument&quot;: {
                    &quot;Statement&quot;: [
                        {
                            &quot;Effect&quot;: &quot;Allow&quot;,
                            &quot;Principal&quot;: {&quot;Service&quot;: [ &quot;lambda.amazonaws.com&quot; ]},
                            &quot;Action&quot;: [ &quot;sts:AssumeRole&quot; ]
                        }
                    ]
                },
                &quot;Policies&quot;: [
                    {
                        &quot;PolicyName&quot;: &quot;lambda&quot;,
                        &quot;PolicyDocument&quot;: {
                            &quot;Statement&quot;: [
                                {
                                    &quot;Effect&quot;: &quot;Allow&quot;,
                                    &quot;Action&quot;: [
                                        &quot;logs:CreateLogGroup&quot;,
                                        &quot;logs:CreateLogStream&quot;,
                                        &quot;logs:PutLogEvents&quot;
                                    ],
                                    &quot;Resource&quot;: &quot;*&quot;
                                },
                                {
                                    &quot;Effect&quot;: &quot;Allow&quot;,
                                    &quot;Action&quot;: &quot;ec2:ModifyVpcPeeringConnectionOptions&quot;,
                                    &quot;Resource&quot;: &quot;*&quot;
                                }
                            ]
                        }
                    }
                ]
            }
        },
        &quot;VpcPeeringOptionsLambdaFunction&quot;: {
            &quot;Type&quot;: &quot;AWS::Lambda::Function&quot;,
            &quot;Properties&quot;: {
                &quot;Description&quot;: { &quot;Fn::Sub&quot;: &quot;VPC Peering Connection Options (${AWS::StackName}&quot; },
                &quot;Code&quot;: {
                    &quot;ZipFile&quot;:  { &quot;Fn::Join&quot;: [
                        &quot;\n&quot;,
                        [
                            &quot;const response = require('cfn-response');&quot;,
                            &quot;const aws = require('aws-sdk');&quot;,
                            &quot;const ec2 = new aws.EC2();&quot;,
                            &quot;exports.handler = async(event, context) =&gt; {&quot;,
                            &quot;  const id = event.ResourceProperties.VpcPeeringConnectionId;&quot;,
                            &quot;  const allowDnsResolutionFromRemoteVpc = event.RequestType !== 'Delete';&quot;,
                            &quot;  if (id) {&quot;,
                            &quot;    try {&quot;,
                            &quot;      const data = ec2.modifyVpcPeeringConnectionOptions({&quot;,
                            &quot;        VpcPeeringConnectionId: id,&quot;,
                            &quot;        AccepterPeeringConnectionOptions: {&quot;,
                            &quot;          AllowDnsResolutionFromRemoteVpc: allowDnsResolutionFromRemoteVpc&quot;,
                            &quot;        }&quot;,
                            &quot;      });&quot;,
                            &quot;      return await response.send(event, context, response.SUCCESS, data, id);&quot;,
                            &quot;    } catch (err) {&quot;,
                            &quot;      const error = 'modifyVpcPeeringConnectionOptions call failed';&quot;,
                            &quot;      console.log(error, err);&quot;,
                            &quot;      return await response.send(event, context, response.FAILED, { Error: error }, id);&quot;,
                            &quot;    }&quot;,
                            &quot;  } else {&quot;,
                            &quot;    const error = 'VpcPeeringConnectionId not specified';&quot;,
                            &quot;    console.log(error);&quot;,
                            &quot;    return await response.send(event, context, response.FAILED, { Error: error });&quot;,
                            &quot;  }&quot;,
                            &quot;};&quot;
                        ]
                    ]}
                },
                &quot;Handler&quot;: &quot;index.handler&quot;,
                &quot;Runtime&quot;: &quot;nodejs24.x&quot;,
                &quot;Timeout&quot;: &quot;30&quot;,
                &quot;Role&quot;: { &quot;Fn::GetAtt&quot;: [ &quot;VpcPeeringOptionsRole&quot;, &quot;Arn&quot; ]}
            }
        },
        &quot;VpcPeeringOptions&quot;: {
            &quot;Type&quot;: &quot;Custom::VpcPeeringOptions&quot;,
            &quot;Properties&quot;: {
                &quot;ServiceToken&quot;: { &quot;Fn::GetAtt&quot;: [ &quot;DnsResolutionLambdaFunction&quot;, &quot;Arn&quot; ]},
                &quot;VpcPeeringConnectionId&quot;: { &quot;Ref&quot;: &quot;BuildVpcPeeringConnection&quot; }
            }
        }
    }
}
</code></pre>

Q: Can you disable content diffing to improve SwiftUI Table performance? A: <h1>A Modern macOS 26+ Approach</h1>
<h3>The Problem</h3>
<p>&quot;Just add <code>.id(UUID())</code> to <code>Table</code>&quot; doesn't work. In macOS 26, it causes a completely frozen Table and, if you have column customization enabled, it produces an infinite loop of view body renders, which you can see by adding a <code>_ = Self._printChanges()</code> to your view body. Each time the <code>Table</code> renders with a new ID, SwiftUI updates the <code>columnCustomization</code>, triggering another render, another new ID, ad infinitum. (SwiftUI must tie the columnCustomization object to the Table's ID internally, which sort of makes sense.)</p>
<h3>The Workaround</h3>
<p>We need a random UUID <em>only</em> while our Table is reloading after we change its data array. And <em>while</em> the Table has a random UUID assigned, we must intercept and discard the TableCustomization parameter so it doesn't trigger an infinite render loop. Once the reload is complete, we then give the Table a stable ID and apply our actual columnCustomization. Like this:</p>
<pre><code>struct FooView: View
{
    static let stableTableID: UUID = UUID(uuidString: &quot;1FC4D4D6-55E4-47C5-9DD7-8284E016D1FF&quot;)!

    @AppStorage(&quot;TableConfig&quot;) private var columnCustomization: TableColumnCustomization&lt;Model&gt;

    @State private var tableData: [Model] = []
    @State private var isLoading: Bool = true


    // This custom binding re-routes the column customization to nothing while we're loading, which prevents infinite view re-renders. 
    private var columnCustomizationBinding: Binding&lt;TableColumnCustomization&lt;Model&gt;&gt; {
        Binding {
            if viewModel.isLoading {
                let copy = columnCustomization      // Don't return the original or SwiftUI will reset it to the initial default state because our Table ID is changing.
                return copy
            }
            return columnCustomization
        } set: { newValue in
            if isLoading == false {
                columnCustomization = newValue
            }
        }
    }


    var body: some View
    {
        Table(tableData, columnCustomization: columnCustomizationBinding) { 
           ... 
        }
        .id(isLoading ? UUID() : Self.stableTableID)
    }
}
</code></pre>
<p>Now, the key to making this work is to update <code>tableData</code> in a three-step process:</p>
<ol>
<li>First set <code>isLoading = true</code> on the view.</li>
<li>WAIT a fraction of a second (so that the view body is re-evaluated with the new <code>isLoading</code> condition. THEN update <code>tableData</code>.</li>
<li>After you update <code>tableData</code>, WAIT a fraction of a second, then set <code>isLoading</code> to false.</li>
</ol>
<p>In my testing, a 0.1 second delay is all it takes. This is not noticeable to humans, but is a lifetime to a computer.</p>
<p>To accomplish this delay, I use a convenience extension on <code>Task</code>:</p>
<pre><code>extension Task where Failure == any Error
{
    @discardableResult static func delayed(byTimeInterval delayInterval: TimeInterval, priority: TaskPriority? = nil, operation: @escaping @Sendable () async throws -&gt; Success) -&gt; Task {
        Task(priority: priority) {
            let delay = UInt64(delayInterval * 1_000_000_000)
            try await Task&lt;Never, Never&gt;.sleep(nanoseconds: delay)
            return try await operation()
        }
    }
}
</code></pre>
<p>So my data update (in a ViewModel or wherever) might look like this:</p>
<pre><code>func reloadTableData()
{
   isLoading = true

   Task.delayed(timeInterval: 0.1, priority: .userInitiated) { @MainActor in

      //
      // fetch new data here, assign to self.tableData property.
      //

      Task.delayed(timeInterval: 0.1, priority: .userInitated) { @MainActor in
         self.isLoading = false
      }
   }
}

</code></pre>
<p>Note that the custom binding returns a <em>copy</em> of our actual <code>ColumnCustomization&lt;Model&gt;</code> value. Do NOT return the original value or SwiftUI will reset it to the initial default for the Table, clobbering any customizations your user has made. Returning a copy prevents the Table from briefly flashing its default arrangement during the reload process; the UI remains stable throughout the reload.</p>
<h3>Outcome</h3>
<p>SwiftUI will now reload the entire Table rather than trying to diff the massive datasource behind it. You will no longer see hangs.</p>
<p>You can use this same technique when changing the sortOrder. Follow the same three-step process and, in step #2, resort your data array and set it. You'll find that sorting Table columns is then just about as fast as in AppKit's NSTableView.</p>
<h3>Conclusion</h3>
<p>Should SwiftUI be smart enough to avoid attempting to diff an 80,000 row <code>Table</code> and just reload the whole thing? Yes.</p>
<p>Should SwiftUI at the VERY least be smart enough to diff only the actual rows that are on-screen and could possibly be involved in any sort of update animation? Double-Yes.</p>
<p>I've shown this to Apple with demo code, Instrument traces, etc. Until they fix it, this is the only workaround I have found that allows fast <code>Table</code> reloads while preserving column customization. My only thought for how Apple shipped <code>Table</code> in this condition is that nobody bothered to really exercise it on macOS with anything more than a tiny demo amount of data.</p>
